"""
This module holds the base class for the log file providers for the different trace types.
"""


class LogFileProviderStrategy:
    """
    This class defines the base class for log file providers for different network element types.

    It contains "get_..._log_file" methods for the different log types, which takes as input:

      * the subdirectory with the name of the collector under the target directory, that was used during
        collect_collector, where the log files have been stored
      * the collector configuration

    The method returns the list of log file paths for the given collector of the given log type.

    The concrete subclass needs to implement the unpacking or conversion, if it is wished by
    the user.
    """

    def __init__(self, collector_configuration_data, **kwargs):
        """
        Create LogFileProviderStrategy object.

        :param CollectorConfigurationData collector_configuration_data:
            collector configurations for taf.collectors.core and
            mapping from log_type and network_element to collector_configuration
        """
        super().__init__(**kwargs)
        self._collector_configuration_data = collector_configuration_data
